use split_decls_genesis :: ourprelude :: * ; use crate :: graph :: { DirectedGraph , Predecessors , Successors } ; #[doc = " View that reverses the direction of edges in its underlying graph, so that"] #[doc = " successors become predecessors and vice-versa."] #[doc = ""] #[doc = " Because of `impl<G: Graph> Graph for &G`, the underlying graph can be"] #[doc = " wrapped by-reference instead of by-value if desired."] #[derive (Clone , Copy , Debug)] pub struct ReversedGraph < G > { pub inner : G , } impl < G > ReversedGraph < G > { pub fn new (inner : G) -> Self { Self { inner } } } impl < G : DirectedGraph > DirectedGraph for ReversedGraph < G > { type Node = G :: Node ; fn num_nodes (& self) -> usize { self . inner . num_nodes () } } impl < G : Predecessors > Successors for ReversedGraph < G > { fn successors (& self , node : Self :: Node) -> impl Iterator < Item = Self :: Node > { self . inner . predecessors (node) } } impl < G : Successors > Predecessors for ReversedGraph < G > { fn predecessors (& self , node : Self :: Node) -> impl Iterator < Item = Self :: Node > { self . inner . successors (node) } }